'use client';

import { usePathname, useSearchParams } from 'next/navigation';
import {
  default as React,
  Suspense,
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
  type CSSProperties,
  type PointerEvent
} from 'react';
import type { SessionRecord } from '@chirality/runtime-contracts/types';
import { listHarnessSessions, harnessApiErrorMessage } from '../../lib/harness/client';
import type { SelectedSessionReplayState } from '../../lib/woven-dialogue/contracts';
import { buildRecordedAgentHierarchy } from '../../lib/woven-dialogue/recorded-agent-hierarchy';
import { guardRecordedSessionSelection } from '../../lib/woven-dialogue/guarded-session-selection';
import {
  createSelectedSessionReplayLoader,
  type SelectedSessionReplayLoader
} from '../../lib/woven-dialogue/selected-session-replay';
import {
  clearProjectScopedWovenWorkspaceState,
  createDefaultWovenWorkspaceState,
  readWovenWorkspaceStateFromStorage,
  recordWovenSessionSurface,
  writeWovenWorkspaceStateToStorage,
  type WovenWorkspaceState
} from '../../lib/woven-dialogue/woven-workspace-state';
import { useHarnessStreaming } from '../workspace/harness-events-provider';
import { useWorkspace } from '../workspace/workspace-provider';
import { ChatPanel } from '../shell/chat-panel';
import { PersonaPicker } from '../shell/persona-picker';
import { useRuntimeEpoch } from '../shell/runtime-connectivity-provider';
import { ShellFrame } from '../shell/shell-frame';
import { ActivityShelf } from './activity-shelf';
import { CoordinationPanel } from './coordination-panel';
import { RightPanel } from './right-panel';
import { DialogueViewport } from './dialogue-viewport';
import { Navigator, type WovenSurface } from './navigator';
import { SelectedSessionReplayLens } from './selected-session-replay-lens';

type WovenDialogueShellProps = {
  defaultSurface: WovenSurface;
};

type ResizeTarget = 'navigator' | 'coordination' | 'activity';

function selectedReplayId(state: SelectedSessionReplayState): string | undefined {
  if (state.status === 'READY') {
    return state.projection.selectedSessionId;
  }
  if (state.status === 'LOADING' || state.status === 'UNAVAILABLE') {
    return state.selectedSessionId;
  }
  return undefined;
}

function clamp(value: number, minimum: number, maximum: number): number {
  return Math.max(minimum, Math.min(maximum, value));
}

export function WovenDialogueShell(_props: WovenDialogueShellProps): JSX.Element {
  const pathname = usePathname();
  const searchParams = useSearchParams();
  const { projectRoot } = useWorkspace();
  const streaming = useHarnessStreaming();
  const runtimeEpoch = useRuntimeEpoch();
  const [primarySessionId, setPrimarySessionId] = useState<string>();
  const [workspaceState, setWorkspaceState] = useState<WovenWorkspaceState>(
    createDefaultWovenWorkspaceState
  );
  const [availableWidth, setAvailableWidth] = useState(1440);
  const workspaceRef = useRef<HTMLElement | null>(null);
  const [coordinationView, setCoordinationView] = useState<'session' | 'agents'>('agents');
  const rightView = workspaceState.rightPanelView === 'agents' ? 'agents' : 'files';
  const widthKey = rightView === 'files' && workspaceState.openDocumentPath ? 'document' : rightView === 'agents' && coordinationView === 'session' ? 'session' : rightView;
  const rightWidth = workspaceState.rightPanelWidths?.[widthKey] ?? (widthKey === 'files' ? 300 : widthKey === 'agents' ? 360 : 480);
  const maximumRightWidth = Math.max(280, Math.min(Math.round(availableWidth * 0.6 / 8) * 8, availableWidth - (workspaceState.navigatorCollapsed ? 56 : workspaceState.navigatorWidth) - 444));
  const [stateHydrated, setStateHydrated] = useState(false);
  const [sessions, setSessions] = useState<SessionRecord[]>([]);
  const [sessionsLoading, setSessionsLoading] = useState(false);
  const [sessionsError, setSessionsError] = useState<string | null>(null);
  const [sessionRefreshToken, setSessionRefreshToken] = useState(0);
  const replayLoaderRef = useRef<SelectedSessionReplayLoader>();
  const previousProjectRootRef = useRef(projectRoot);
  const [replayState, setReplayState] = useState<SelectedSessionReplayState>({
    status: 'IDLE'
  });
  const dialogueInputRef = useRef<HTMLInputElement | null>(null);
  const resizeRef = useRef<{
    target: ResizeTarget;
    startX: number;
    startY: number;
    startValue: number;
  } | null>(null);

  if (!replayLoaderRef.current) {
    replayLoaderRef.current = createSelectedSessionReplayLoader();
  }

  useEffect(() => {
    const loader = replayLoaderRef.current as SelectedSessionReplayLoader;
    const unsubscribe = loader.subscribe(setReplayState);
    return () => {
      unsubscribe();
      loader.dispose();
    };
  }, []);

  useEffect(() => {
    if (typeof window === 'undefined') {
      return;
    }
    const stored = readWovenWorkspaceStateFromStorage(window.localStorage);
    setWorkspaceState(stored);
    // Retired Work preferences fall back to the recorded Agents projection.
    setCoordinationView('agents');
    setStateHydrated(true);
  }, []);

  useEffect(() => {
    if (!stateHydrated || typeof window === 'undefined') {
      return;
    }
    writeWovenWorkspaceStateToStorage(window.localStorage, workspaceState);
  }, [stateHydrated, workspaceState]);

  useEffect(() => {
    const element = workspaceRef.current;
    if (!element || typeof ResizeObserver === 'undefined') return;
    const observer = new ResizeObserver(entries => {
      const width = entries[0]?.contentRect.width;
      if (width) setAvailableWidth(width);
    });
    observer.observe(element);
    return () => observer.disconnect();
  }, []);

  // The recorded session list carries no surface field, so the shell tags the
  // dialogue surface when a session is first observed. Local
  // annotation only (no project truth); first attribution wins, so this is a
  // no-op — same state reference — for every session already tagged.
  useEffect(() => {
    if (!stateHydrated || !primarySessionId) {
      return;
    }
    setWorkspaceState((current) =>
      recordWovenSessionSurface(current, primarySessionId, 'dialogue')
    );
  }, [primarySessionId, stateHydrated]);

  useEffect(() => {
    replayLoaderRef.current?.cancel();
    setSessions([]);
    setSessionsError(null);
    if (
      previousProjectRootRef.current &&
      previousProjectRootRef.current !== projectRoot
    ) {
      setWorkspaceState(clearProjectScopedWovenWorkspaceState);
    }
    previousProjectRootRef.current = projectRoot;
  }, [projectRoot]);

  useEffect(() => {
    if (primarySessionId) {
      setSessionRefreshToken((token) => token + 1);
    }
  }, [primarySessionId, streaming]);

  useEffect(() => {
    if (!projectRoot) {
      setSessions([]);
      setSessionsLoading(false);
      return;
    }

    let cancelled = false;
    setSessionsLoading(true);
    setSessionsError(null);
    listHarnessSessions(projectRoot)
      .then((records) => {
        if (!cancelled) {
          setSessions(records);
        }
      })
      .catch((error) => {
        if (!cancelled) {
          setSessionsError(harnessApiErrorMessage(error));
        }
      })
      .finally(() => {
        if (!cancelled) {
          setSessionsLoading(false);
        }
      });

    return () => {
      cancelled = true;
    };
    // `runtimeEpoch` re-lists after a reconnect. The Navigator's flat list and
    // the Coordination panel's hierarchy are both projections of `sessions`, so
    // one re-list repairs all three surfaces at once.
  }, [projectRoot, sessionRefreshToken, runtimeEpoch]);

  // Read at reconnect time only, so the recovery effect below can depend on the
  // epoch alone: depending on the replay state itself would re-arm the effect
  // with every load it performs.
  const replayStateRef = useRef(replayState);
  replayStateRef.current = replayState;
  const sessionsRef = useRef(sessions);
  sessionsRef.current = sessions;

  // A replay lens left showing UNAVAILABLE is the same stale-error class as the
  // panes above, and it is still on screen — the lens is only hidden when the
  // state is IDLE. Reload it once, straight through the loader: the selection
  // guard is for operator clicks, and it answers UNCHANGED for a re-request of
  // the session already selected.
  useEffect(() => {
    if (runtimeEpoch === 0) {
      return;
    }
    const current = replayStateRef.current;
    if (current.status !== 'UNAVAILABLE') {
      return;
    }
    void replayLoaderRef.current?.load(current.selectedSessionId, {
      observedAt: new Date().toISOString(),
      availableSessionIds: new Set(
        sessionsRef.current.map((session) => session.sessionId)
      )
    });
  }, [runtimeEpoch]);

  const hierarchy = useMemo(() => {
    const observedAt = new Date().toISOString();
    return buildRecordedAgentHierarchy(
      sessions.map((session) => {
        const source = session as SessionRecord & Record<string, unknown>;
        return {
          ...source,
          sourceReference: `session:${session.sessionId}`,
          observedAt,
          currency: 'UNKNOWN',
          status: source.status,
          role: source.role
        };
      })
    );
  }, [sessions]);

  const legacyHref = useMemo(() => {
    const params = new URLSearchParams(searchParams.toString());
    params.set('legacy', '1');
    return `${pathname}?${params.toString()}`;
  }, [pathname, searchParams]);

  const updateWorkspaceState = useCallback(
    (patch: Partial<WovenWorkspaceState>): void => {
      setWorkspaceState((current) => ({ ...current, ...patch }));
    },
    []
  );

  const restoreExpanded = useCallback(() => {
    setWorkspaceState(current => {
      if (!current.rightPanelExpanded) return current;
      const previous = current.preExpandState;
      return { ...current, rightPanelExpanded: false, preExpandState: null,
        navigatorCollapsed: previous?.leftCollapsed ?? current.navigatorCollapsed,
        rightPanelWidths: { ...current.rightPanelWidths, [widthKey]: previous?.rightWidth ?? rightWidth }
      };
    });
  }, [widthKey, rightWidth]);

  const returnToPrimaryDialogue = useCallback((): void => {
    replayLoaderRef.current?.cancel();
    updateWorkspaceState({ selectedReplaySessionId: null });
    window.requestAnimationFrame(() => {
      const input = document.querySelector<HTMLInputElement>('[data-chat-input="primary"]');
      dialogueInputRef.current = input;
      input?.focus();
    });
  }, [updateWorkspaceState]);

  const loadReplay = useCallback(
    (sessionId: string): void => {
      const decision = guardRecordedSessionSelection({
        currentState: replayState,
        requestedSessionId: sessionId,
        primarySessionId,
        recordedSessionIds: sessions.map((session) => session.sessionId),
        liveTurnActive: streaming,
        replayIsolationAvailable: true
      });
      if (decision.outcome === 'RETURN_TO_PRIMARY') {
        returnToPrimaryDialogue();
        return;
      }
      if (decision.outcome === 'UNCHANGED') {
        restoreExpanded();
        updateWorkspaceState({ coordinationCollapsed: false, rightPanelView: 'agents' });
        setCoordinationView('session');
        return;
      }
      if (decision.outcome !== 'SELECT_REPLAY') {
        return;
      }

      restoreExpanded();
      updateWorkspaceState({
        selectedReplaySessionId: sessionId,
        rightPanelView: 'agents',
        coordinationCollapsed: false
      });
      setCoordinationView('session');
      void replayLoaderRef.current?.load(sessionId, {
        observedAt: new Date().toISOString(),
        availableSessionIds: new Set(sessions.map((session) => session.sessionId))
      });
    },
    [
      primarySessionId,
      replayState,
      returnToPrimaryDialogue,
      restoreExpanded,
      sessions,
      streaming,
      updateWorkspaceState
    ]
  );

  const beginResize = useCallback(
    (event: PointerEvent<HTMLDivElement>, target: ResizeTarget): void => {
      if (event.button !== 0) {
        return;
      }
      event.preventDefault();
      if (target === 'coordination') restoreExpanded();
      const startValue =
        target === 'navigator'
          ? workspaceState.navigatorWidth
          : target === 'coordination'
            ? rightWidth
            : workspaceState.activityHeight;
      resizeRef.current = {
        target,
        startX: event.clientX,
        startY: event.clientY,
        startValue
      };
    },
    [workspaceState, rightWidth, restoreExpanded]
  );

  useEffect(() => {
    const handleMove = (event: globalThis.PointerEvent): void => {
      const resize = resizeRef.current;
      if (!resize) {
        return;
      }
      if (resize.target === 'navigator') {
        updateWorkspaceState({
          navigatorWidth: clamp(resize.startValue + event.clientX - resize.startX, 220, 620),
          navigatorCollapsed: false
        });
      } else if (resize.target === 'coordination') {
        const width = clamp(resize.startValue - event.clientX + resize.startX, 280, maximumRightWidth);
        setWorkspaceState(current => ({ ...current,
          rightPanelWidths: { ...current.rightPanelWidths, [widthKey]: width },
          coordinationWidth: width, coordinationCollapsed: false
        }));
      } else {
        updateWorkspaceState({
          activityHeight: clamp(resize.startValue - event.clientY + resize.startY, 120, 480),
          activityCollapsed: false
        });
      }
    };
    const handleUp = (): void => {
      resizeRef.current = null;
    };
    window.addEventListener('pointermove', handleMove);
    window.addEventListener('pointerup', handleUp);
    window.addEventListener('pointercancel', handleUp);
    return () => {
      window.removeEventListener('pointermove', handleMove);
      window.removeEventListener('pointerup', handleUp);
      window.removeEventListener('pointercancel', handleUp);
    };
  }, [updateWorkspaceState, widthKey, maximumRightWidth]);

  const resizeByKeyboard = useCallback(
    (target: ResizeTarget, key: string, shift: boolean): void => {
      if (target === 'coordination') restoreExpanded();
      const step = shift ? 40 : 16;
      if (target === 'navigator') {
        const value =
          key === 'Home'
            ? 220
            : key === 'End'
              ? 620
              : workspaceState.navigatorWidth + (key === 'ArrowRight' ? step : -step);
        updateWorkspaceState({
          navigatorWidth: clamp(value, 220, 620),
          navigatorCollapsed: key === 'Home'
        });
      } else if (target === 'coordination') {
        const value =
          key === 'Home'
            ? 280
            : key === 'End'
              ? maximumRightWidth
              : rightWidth + (key === 'ArrowLeft' ? step : -step);
        updateWorkspaceState({
          rightPanelWidths: { ...workspaceState.rightPanelWidths, [widthKey]: clamp(value, 280, maximumRightWidth) },
          coordinationWidth: clamp(value, 280, maximumRightWidth),
          coordinationCollapsed: key === 'Home'
        });
      } else {
        const value =
          key === 'Home'
            ? 120
            : key === 'End'
              ? 480
              : workspaceState.activityHeight + (key === 'ArrowUp' ? step : -step);
        updateWorkspaceState({
          activityHeight: clamp(value, 120, 480),
          activityCollapsed: key === 'Home'
        });
      }
    },
    [updateWorkspaceState, workspaceState, rightWidth, widthKey, restoreExpanded, maximumRightWidth]
  );

  const toggleExpanded = () => {
    if (workspaceState.rightPanelExpanded) { restoreExpanded(); return; }
    updateWorkspaceState({ rightPanelExpanded: true,
      preExpandState: { rightWidth, leftCollapsed: workspaceState.navigatorCollapsed },
      navigatorCollapsed: true, coordinationCollapsed: false });
  };
  const stacked = availableWidth < 960;
  const leftWidth = workspaceState.navigatorCollapsed ? 56 : Math.min(workspaceState.navigatorWidth, Math.max(220, availableWidth - 724));
  const visibleRightWidth = workspaceState.coordinationCollapsed ? 56 : Math.max(280, Math.min(
    workspaceState.rightPanelExpanded ? Math.round(availableWidth * 0.6 / 8) * 8 : rightWidth,
    availableWidth - leftWidth - 444
  ));
  const style = {
    ...(!stacked ? { gridTemplateColumns: `${leftWidth}px 12px minmax(420px, 1fr) 12px ${visibleRightWidth}px` } : {}),
    '--woven-activity-height': `${workspaceState.activityCollapsed ? 68 : workspaceState.activityHeight}px`
  } as CSSProperties;
  const replayVisible = replayState.status !== 'IDLE';

  return (
    <ShellFrame
      section="CHAT"
      title="Woven Dialogue"
      subtitle="A shared professional workspace where dialogue produces inspectable artifacts and governed work."
      variant="workspace"
    >
      <section ref={workspaceRef} className={`woven-workspace woven-t3-workspace${stacked ? ' is-stacked' : ''}`} style={style} data-woven-surface="dialogue">
        <style>{`
          .woven-t3-workspace .woven-right-panel { display:flex; flex-direction:column; min-width:0; height:100%; overflow:auto; }
          .woven-t3-workspace .woven-right-panel > .panel { min-height:0; flex:1; }
          .woven-t3-workspace .woven-right-panel nav { overflow-wrap:anywhere; min-width:0; }
          .woven-t3-workspace .tree-item-name { text-align:left; overflow-wrap:anywhere; min-width:0; }
          .woven-t3-workspace .tree-item-name[aria-current=true] { background:var(--ground); font-weight:600; }
          .shell--workspace:has(> .woven-t3-workspace.is-stacked) { height:auto; min-height:100vh; overflow:visible; }
          .woven-t3-workspace.is-stacked { grid-template-columns:minmax(0,1fr); grid-template-rows:minmax(620px,70vh) auto auto 12px auto; height:auto; overflow:visible; }
          .woven-t3-workspace.is-stacked > .woven-dialogue-region { grid-column:1; grid-row:1; }
          .woven-t3-workspace.is-stacked > .woven-region--navigator { grid-column:1; grid-row:2; max-height:360px; }
          .woven-t3-workspace.is-stacked > .woven-region--coordination { grid-column:1; grid-row:3; height:520px; }
          .woven-t3-workspace.is-stacked > .woven-resize-handle--vertical { display:none; }
          .woven-t3-workspace.is-stacked > .woven-resize-handle--horizontal { grid-column:1; grid-row:4; }
          .woven-t3-workspace.is-stacked > .woven-activity { grid-column:1; grid-row:5; }
        `}</style>
        <main className="woven-dialogue-region" aria-label="Primary Dialogue" onInputCapture={(event) => {
          if ((event.target as HTMLElement).matches?.('[data-chat-input="primary"]')) restoreExpanded();
        }}>
          <DialogueViewport
            primaryDialogue={
              <>
                <div className="woven-dialogue-toolbar">
                  <div>
                    <p className="woven-eyebrow">Primary conversation</p>
                    <h2>Dialogue</h2>
                  </div>
                  <PersonaPicker disabled={streaming} />
                </div>
                <Suspense fallback={<p className="panel-empty">Loading primary dialogue…</p>}>
                  <ChatPanel onActiveSessionChange={setPrimarySessionId} />
                </Suspense>
              </>
            }
          />
        </main>

        <div
          className={
            workspaceState.navigatorCollapsed
              ? 'woven-region woven-region--navigator is-collapsed'
              : 'woven-region woven-region--navigator'
          }
        >
          <button
            type="button"
            className="woven-region-toggle button-muted"
            onClick={() => {
              updateWorkspaceState({
                navigatorCollapsed: !workspaceState.navigatorCollapsed
              });
            }}
          >
            {workspaceState.navigatorCollapsed ? 'Open Navigator' : 'Close Navigator'}
          </button>
          {!workspaceState.navigatorCollapsed ? (
            <Navigator
              activeSurface="dialogue"
              legacyHref={legacyHref}
              sessions={sessions}
              sessionSurfaces={workspaceState.sessionSurfaces}
              liveSessionId={primarySessionId}
              selectedSessionId={selectedReplayId(replayState)}
              selectionDisabled={streaming}
              sessionsLoading={sessionsLoading}
              sessionsError={sessionsError}
              onOpenSurface={returnToPrimaryDialogue}
              onSelectSession={loadReplay}
            />
          ) : (
            <span className="woven-collapsed-label">Navigator</span>
          )}
        </div>

        <div
          className="woven-resize-handle woven-resize-handle--vertical woven-resize-handle--navigator"
          role="separator"
          tabIndex={0}
          aria-label="Resize Navigator"
          aria-orientation="vertical"
          aria-valuemin={220}
          aria-valuemax={620}
          aria-valuenow={workspaceState.navigatorWidth}
          onPointerDown={(event) => {
            beginResize(event, 'navigator');
          }}
          onKeyDown={(event) => {
            if (
              ['ArrowLeft', 'ArrowRight', 'Home', 'End'].includes(event.key)
            ) {
              event.preventDefault();
              resizeByKeyboard('navigator', event.key, event.shiftKey);
            }
          }}
        />

        <div
          className="woven-resize-handle woven-resize-handle--vertical woven-resize-handle--coordination"
          role="separator"
          tabIndex={0}
          aria-label="Resize Coordination Panel"
          aria-orientation="vertical"
          aria-valuemin={280}
          aria-valuemax={maximumRightWidth}
          aria-valuenow={rightWidth}
          onPointerDown={(event) => {
            beginResize(event, 'coordination');
          }}
          onKeyDown={(event) => {
            if (
              ['ArrowLeft', 'ArrowRight', 'Home', 'End'].includes(event.key)
            ) {
              event.preventDefault();
              resizeByKeyboard('coordination', event.key, event.shiftKey);
            }
          }}
        />

        <aside
          className={
            workspaceState.coordinationCollapsed
              ? 'woven-region woven-region--coordination is-collapsed'
              : 'woven-region woven-region--coordination'
          }
        >
          <button
            type="button"
            className="woven-region-toggle button-muted"
            onClick={() => {
              updateWorkspaceState({
                coordinationCollapsed: !workspaceState.coordinationCollapsed
              });
            }}
          >
            {workspaceState.coordinationCollapsed ? 'Open Coordination' : 'Close Coordination'}
          </button>
          {!workspaceState.coordinationCollapsed ? (
            <RightPanel state={workspaceState} sessionOpen={coordinationView === 'session'}
              replayState={replayState} recordedSessionIds={sessions.map(session => session.sessionId)}
              primarySessionId={primarySessionId} liveTurnActive={streaming} onOpenParent={loadReplay}
              onView={(view) => {
                restoreExpanded();
                updateWorkspaceState({ rightPanelView: view, ...(view === 'files' ? { openDocumentPath: null } : {}) });
                if (view === 'agents') setCoordinationView('agents');
              }}
              onOpenFile={(filePath) => {
                if (!projectRoot) return;
                const prefix = `${projectRoot.replace(/\/$/, '')}/`;
                if (!filePath.startsWith(prefix)) return;
                restoreExpanded();
                updateWorkspaceState({ openDocumentPath: filePath.slice(prefix.length), rightPanelView: 'files' });
              }}
              onExpand={toggleExpanded}
              onRefreshSessions={() => setSessionRefreshToken(token => token + 1)}
              onClose={() => {
                restoreExpanded();
                if (rightView === 'files' && workspaceState.openDocumentPath) updateWorkspaceState({ openDocumentPath: null });
                else if (rightView === 'agents' && coordinationView === 'session') setCoordinationView('agents');
                else updateWorkspaceState({ coordinationCollapsed: true });
              }}
              coordination={<CoordinationPanel
              activeView={coordinationView}
              replaySlot={
                replayVisible ? (
                  <SelectedSessionReplayLens
                    state={replayState}
                    primarySessionId={primarySessionId}
                    onReturnToPrimary={returnToPrimaryDialogue}
                    onRetry={() => {
                      const sessionId = selectedReplayId(replayState);
                      if (sessionId) {
                        void replayLoaderRef.current?.load(sessionId, {
                          observedAt: new Date().toISOString(),
                          availableSessionIds: new Set(sessions.map((session) => session.sessionId))
                        });
                      }
                    }}
                  />
                ) : undefined
              }
              hierarchy={hierarchy}
              sessionsLoading={sessionsLoading}
              sessionsError={sessionsError}
              selectedSessionId={selectedReplayId(replayState)}
              selectionDisabled={streaming}
              onSelectView={(coordinationView) => {
                restoreExpanded();
                setCoordinationView(coordinationView);
              }}
              onRefreshSessions={() => {
                setSessionRefreshToken((token) => token + 1);
              }}
              onSelectSession={loadReplay}
            />} />
          ) : (
            <span className="woven-collapsed-label">Coordination</span>
          )}
        </aside>

        <div
          className="woven-resize-handle woven-resize-handle--horizontal"
          role="separator"
          tabIndex={0}
          aria-label="Resize Activity Shelf"
          aria-orientation="horizontal"
          aria-valuemin={120}
          aria-valuemax={480}
          aria-valuenow={workspaceState.activityHeight}
          onPointerDown={(event) => {
            beginResize(event, 'activity');
          }}
          onKeyDown={(event) => {
            if (['ArrowUp', 'ArrowDown', 'Home', 'End'].includes(event.key)) {
              event.preventDefault();
              resizeByKeyboard('activity', event.key, event.shiftKey);
            }
          }}
        />

        <ActivityShelf
          collapsed={workspaceState.activityCollapsed}
          onToggleCollapsed={() => {
            updateWorkspaceState({
              activityCollapsed: !workspaceState.activityCollapsed
            });
          }}
        />
      </section>
    </ShellFrame>
  );
}

'use client';

import React, { useEffect, useRef, useState } from 'react';
import type { SelectedSessionReplayState } from '../../lib/woven-dialogue/contracts';
import { guardRecordedSessionSelection } from '../../lib/woven-dialogue/guarded-session-selection';
import { useWorkspace } from '../workspace/workspace-provider';
import { FileTreePanel } from '../shell/file-tree-panel';
import { DocumentView, handoffDocument } from '../shell/document-view';
import type { WovenWorkspaceState } from '../../lib/woven-dialogue/woven-workspace-state';

/** Deterministic projection of recorded metadata; never a generated purpose/result narrative. */
export function deriveSessionMenu(
  state: SelectedSessionReplayState,
  recordedSessionIds: readonly string[],
  primarySessionId: string | undefined,
  liveTurnActive: boolean
): { id?: string; summary?: string; parentId?: string; parentDisabledReason?: string } {
  if (state.status === 'IDLE') return { parentDisabledReason: 'Select a recorded session first.' };
  const id = state.status === 'READY' ? state.projection.selectedSessionId : state.selectedSessionId;
  if (state.status !== 'READY') return { id, parentDisabledReason: 'Parent information is unavailable until the recorded session loads.' };
  const projection = state.projection;
  const session = projection.session;
  const summary = 'Recorded session metadata (read-only snapshot)\n' + JSON.stringify({
    selectedSessionId: id,
    sourceReference: projection.sourceReference,
    observedAt: projection.observedAt,
    disclosure: projection.disclosure,
    currency: projection.currency,
    sourceEventCount: projection.sourceEventCount,
    renderedItemCount: projection.renderedItemCount,
    malformedLineCount: projection.malformedLineCount,
    ...(session ? { recordedAttribution: {
      sessionId: session.sessionId, sourceReference: session.sourceReference,
      observedAt: session.observedAt, currency: session.currency,
      persona: session.persona, role: session.role, runtimeStatus: session.runtimeStatus,
      providerId: session.providerId, model: session.model, parentage: session.parentage
    } } : {})
  }, null, 2);
  const blocked = (parentDisabledReason: string) => ({ id, summary, parentDisabledReason });
  if (projection.currency === 'CONFLICTING' || projection.disclosure === 'CONFLICTING' ||
      session?.currency === 'CONFLICTING' || (session && session.sessionId !== id) ||
      [...(projection.diagnostics ?? []), ...(session?.diagnostics ?? [])].some(item => item.code.includes('CONFLICT'))) {
    return blocked('Recorded parentage is conflicting; parent navigation is unavailable.');
  }
  if (session?.parentage.state !== 'RECORDED') return blocked('No parent session is recorded.');
  const parent = session.parentage;
  if (!parent.parentAvailable) return blocked('The recorded parent session is unavailable.');
  if (!parent.parentSessionId.trim() || parent.parentSessionId === id) return blocked('Recorded parentage is invalid.');
  const decision = guardRecordedSessionSelection({ currentState: state, requestedSessionId: parent.parentSessionId,
    primarySessionId, recordedSessionIds, liveTurnActive, replayIsolationAvailable: true });
  if (decision.outcome === 'BLOCKED') return blocked(decision.reason === 'LIVE_TURN_ACTIVE'
    ? 'Parent replay is unavailable while a live turn is running.' : 'The recorded parent session is unavailable.');
  return { id, summary, parentId: parent.parentSessionId };
}

type Props = {
  state: WovenWorkspaceState;
  sessionOpen: boolean;
  onView: (view: 'files' | 'agents') => void;
  onOpenFile: (path: string) => void;
  onClose: () => void;
  onExpand: () => void;
  coordination: React.ReactNode;
  onRefreshSessions?: () => void;
  replayState?: SelectedSessionReplayState;
  recordedSessionIds?: readonly string[];
  primarySessionId?: string;
  liveTurnActive?: boolean;
  onOpenParent?: (sessionId: string) => void;
};
export function RightPanel({ state, sessionOpen, onView, onOpenFile, onClose, onExpand, coordination, onRefreshSessions, replayState = { status: 'IDLE' }, recordedSessionIds = [], primarySessionId, liveTurnActive = false, onOpenParent }: Props): JSX.Element {
  const { projectRoot } = useWorkspace();
  const [refresh, setRefresh] = useState(0);
  const [copyStatus, setCopyStatus] = useState<string | null>(null);
  const copyGeneration = useRef(0);
  const sessionMenu = deriveSessionMenu(replayState, recordedSessionIds, primarySessionId, liveTurnActive);
  const [menuError, setMenuError] = useState<string | null>(null);
  // Future stored views must leave existing content reachable, never blank it.
  const view = state.rightPanelView === 'agents' ? 'agents' : 'files';
  const target = view === 'files' ? state.openDocumentPath : null;
  const detailOpen = Boolean(target || (sessionOpen && view === 'agents'));
  const sessionDetail = sessionOpen && view === 'agents';
  useEffect(() => { copyGeneration.current++; setCopyStatus(null); setMenuError(null); }, [sessionMenu.id, target, view]);
  const copy = async (value: string, label: string) => {
    const generation = ++copyGeneration.current; setCopyStatus(null); setMenuError(null);
    try {
      if (!navigator.clipboard?.writeText) throw new Error('Clipboard is unavailable.');
      await navigator.clipboard.writeText(value);
      if (generation === copyGeneration.current) setCopyStatus(`${label} copied.`);
    } catch { if (generation === copyGeneration.current) setMenuError(`Unable to copy ${label.toLowerCase()}.`); }
  };
  return <section className="woven-right-panel" aria-label="Right panel">
    <header className="woven-region-header" style={{ flexWrap: 'wrap' }}>
      {target ? <nav aria-label="Document breadcrumb"><button onClick={() => onView('files')}>Files</button> › <span>{target}</span></nav> :
        sessionOpen && view === 'agents' ? <nav aria-label="Session breadcrumb"><button onClick={() => onView('agents')}>Agents</button> › Session</nav> :
        <div role="tablist" aria-label="Right panel views" onKeyDown={(event) => {
          if (!['ArrowLeft', 'ArrowRight', 'Home', 'End'].includes(event.key)) return;
          event.preventDefault();
          const next = event.key === 'Home' ? 'files' : event.key === 'End' ? 'agents' : view === 'files' ? 'agents' : 'files';
          onView(next);
          event.currentTarget.querySelector<HTMLButtonElement>(`[data-view="${next}"]`)?.focus();
        }}>{(['files', 'agents'] as const).map(item => <button key={item} role="tab" id={`right-tab-${item}`} data-view={item}
          aria-controls="right-view-content" aria-selected={view === item} tabIndex={view === item ? 0 : -1}
          onClick={() => onView(item)}>{item === 'files' ? 'Files' : 'Agents'}</button>)}</div>}
      <div style={{ display: 'flex', flexWrap: 'wrap', gap: 4 }}>
        <details><summary aria-label="Panel menu">Menu</summary>
          {sessionDetail ? <>
            <button type="button" disabled={!sessionMenu.parentId || !onOpenParent}
              aria-describedby={sessionMenu.parentDisabledReason ? 'session-parent-explanation' : undefined}
              onClick={() => { if (sessionMenu.parentId) onOpenParent?.(sessionMenu.parentId); }}>Open parent chat</button>
            {sessionMenu.parentDisabledReason ? <p id="session-parent-explanation">{sessionMenu.parentDisabledReason}</p> : null}
            <button type="button" disabled={!sessionMenu.id} onClick={() => { if (sessionMenu.id) void copy(sessionMenu.id, 'Session id'); }}>Copy session id</button>
            <button type="button" disabled={!sessionMenu.summary} onClick={() => { if (sessionMenu.summary) void copy(sessionMenu.summary, 'Recorded metadata summary'); }}>Copy summary</button>
            {!sessionMenu.summary ? <p>Recorded metadata summary is unavailable until the session loads.</p> : null}
          </> : <button type="button" onClick={() => { setRefresh(value => value + 1); if (view === 'agents') onRefreshSessions?.(); }}>{target ? 'Reload document' : 'Refresh'}</button>}
          {view === 'files' ? <button type="button" disabled={!projectRoot} onClick={() => {
            const value = target ? `${projectRoot?.replace(/\/$/, '')}/${target}` : projectRoot;
            if (value) void copy(value, target ? 'File path' : 'Root path');
          }}>Copy {target ? 'file' : 'root'} path</button> : null}
          {view === 'files' && projectRoot ? <button type="button" onClick={() => {
            void handoffDocument(target ? { projectRoot, target, action: 'reveal' } : { projectRoot, action: 'reveal-root' }).catch(error => setMenuError(error instanceof Error ? error.message : 'Unable to reveal item.'));
          }}>Reveal {target ? 'file' : 'root'} in Finder</button> : null}
          {target && projectRoot ? <button type="button" onClick={() => {
            void handoffDocument({ projectRoot, target, action: 'open' }).catch(error => setMenuError(error instanceof Error ? error.message : 'Unable to open file.'));
          }}>Open in default app</button> : null}
        </details>
        <button type="button" aria-pressed={state.rightPanelExpanded ?? false} onClick={onExpand}>{state.rightPanelExpanded ? 'Return panel' : 'Expand panel'}</button>
        <button type="button" aria-label={detailOpen ? 'Close detail' : 'Collapse right panel'} onClick={onClose}>×</button></div>
    </header>
    {copyStatus ? <p role="status">{copyStatus}</p> : null}
    {menuError ? <p role="alert">{menuError}</p> : null}
    <div id="right-view-content" role={detailOpen ? undefined : 'tabpanel'} aria-labelledby={detailOpen ? undefined : `right-tab-${view}`} style={{ minHeight: 0, flex: 1, overflow: 'auto' }}>
      {view === 'files' ? target ? <DocumentView key={refresh} target={target} expanded={state.rightPanelExpanded} onOpenDocument={relative => { if (projectRoot) onOpenFile(`${projectRoot.replace(/\/$/, '')}/${relative}`); }} /> : <FileTreePanel key={refresh} onOpenFile={onOpenFile} selectedPath={state.openDocumentPath && projectRoot ? `${projectRoot.replace(/\/$/, '')}/${state.openDocumentPath}` : null} /> : coordination}
    </div>
  </section>;
}

